#!/usr/bin/python
# coding=utf-8
"""Hold a package's C# to its kernel, its prior art and its generated files.

Four rules over each ecosystem package that declares its C# parts in
``[tool.m3trik.layers.csharp]`` (``root``, ``order``, ``kernel``: the
declaration check_layers.py holds the asmdef references to, rule 5 there; this
reads the same :class:`check_layers.CSharpLayout`). A ``.cs`` file belongs to
the nearest asmdef above it.

1. **Kernel bypass.** Editor code above the kernel never calls ``Undo.*``,
   ``EditorUtility.DisplayProgressBar`` / ``DisplayCancelableProgressBar`` /
   ``ClearProgressBar`` or ``Debug.Log`` / ``LogWarning`` / ``LogError`` (and
   their ``Format`` forms) / ``LogException`` itself: an action asks its
   ``OpContext`` (which records the undo and shows the progress), an importer
   writes to ``ImportLog``. Nor does it report a problem only when there is a
   context (``ctx?.Issue(...)``, ``ctx != null ? ctx.Issue(...) : ...``, the
   inverted ternary, ``if (ctx != null) ctx.Issue(...)`` with the call anywhere
   in a braced block), which says nothing when no context runs the action:
   ``ctx.Raise(...)`` writes the Console line then; nor call the kernel's
   null-safe extensions (``Raise``, ``Log``, ``Created``, ``Destroy``,
   ``AddComponent``) behind the same checks, which skip the edit or the line
   with no context. A receiver counts when the file types it ``OpContext`` or
   names it like a context, and a ternary or ``if`` only when it checks the
   name it calls (:func:`null_checked_calls`). Editor code is an editor-only assembly
   (``includePlatforms: ["Editor"]``) or a ``#if UNITY_EDITOR`` region; the
   ``Undo`` and ``EditorUtility`` calls are editor API, so they count anywhere.
   The whole file is read at once, so a call wrapped over lines counts, at its
   first line. Comments and strings do not count. Exempt: the declared ``kernel`` part and
   every part ranked below it (they implement those seams), test assemblies
   (``UNITY_INCLUDE_TESTS``) and generated ``*.g.cs``. A violation is named by
   its file's name and call (``bypass: <File>.cs: Undo.RecordObject``, then
   ``(2)``, ``(3)``... for each further one), so a move keeps it frozen.
2. **Prior art.** Every part assembly but a test assembly holds a type whose
   XML doc ``<remarks>`` says ``Prior art:`` -- what the part weighed, and why it
   was or was not adopted (the C# pack; CODE_STANDARD section 15). Named by the
   assembly: ``prior-art: <name>.asmdef``.
3. **Generated files.** Every ``*.g.cs`` under the root opens with the
   ``// <auto-generated>`` header naming its generator (:data:`GENERATORS`), and
   it and its ``.meta`` are exactly what that generator writes now; every file
   the generator writes into the repo exists, under the root. A hand edit, an
   orphan or a stale file fails naming the generator to run. This is the
   generators' own ``--check`` for their C# half, run in-process from their
   target lists, so it needs only pythontk beside m3trik. Strict: never frozen.
4. **Test framework.** A test assembly compiles only where the Test Framework
   is (:func:`test_framework`). Strict: never frozen.

Rules 1 and 2 started by freezing today's violations: ``check_csharp_baseline.json``
lists them, ``--check`` fails only on one it does not list (printing where and
the fix), and reports listed ones that no longer occur so the baseline can
shrink; ``--update`` rewrites it. As in check_layers.py, ``--workspace`` reads
and rewrites that workspace's own copy.

Usage:
    python check_csharp.py [--check] [pkg ...]   # exit 1 on a new violation
    python check_csharp.py --update              # freeze the current violations
"""

import argparse
import bisect
import importlib
import re
import sys
from pathlib import Path
from typing import Callable, Dict, Iterable, List, Optional, Sequence, Tuple

SCRIPTS = Path(__file__).resolve().parent
if str(SCRIPTS) not in sys.path:
    sys.path.insert(0, str(SCRIPTS))

import check_layers as cl  # noqa: E402  (the C# declaration and its layout)

WORKSPACE = SCRIPTS.parents[1]
BASELINE = SCRIPTS / "check_csharp_baseline.json"
BASELINE_DOC = (
    "C# violations frozen when check_csharp.py started holding the line (the "
    "kernel bypass and prior-art rules; generated files are never frozen). "
    "Shrink it; never grow it without a reason in the commit. Rewrite: "
    "check_csharp.py --update."
)


def _targets(stem: str, function: str) -> Callable[[], List[Tuple[Path, str]]]:
    return lambda: getattr(importlib.import_module(stem), function)()


#: Each generator that writes ``*.g.cs``, as its header names it, and the files
#: it writes now (``[(path, text)]``, the ``.meta`` files included).
GENERATORS: Dict[str, Callable[[], List[Tuple[Path, str]]]] = {
    "m3trik/scripts/sync_operation_contract.py": _targets(
        "sync_operation_contract", "targets"
    ),
    "m3trik/scripts/sync_scene_records.py": _targets("sync_scene_records", "cs_targets"),
    "m3trik/scripts/sync_job_queue.py": _targets("sync_job_queue", "targets"),
}

# ---------------------------------------------------------------- lexing
_STRING_START = re.compile(r'\$@"|@\$"|\$"|@"|"')


def code_only(text: str) -> str:
    """*text* with every comment and the contents of every string and char
    literal blanked to spaces (newlines kept, so offsets and lines hold); an
    interpolated string's ``{holes}`` stay code."""
    out = list(text)
    n = len(text)

    def blank(start: int, end: int) -> None:
        for k in range(start, min(end, n)):
            if out[k] != "\n":
                out[k] = " "

    def code(i: int, hole: bool) -> int:
        """Lex code from *i*; in a *hole*, stop at its closing brace."""
        depth = 0
        while i < n:
            c, pair = text[i], text[i : i + 2]
            if pair == "//":
                end = text.find("\n", i)
                end = n if end < 0 else end
                blank(i, end)
                i = end
            elif pair == "/*":
                end = text.find("*/", i + 2)
                end = n if end < 0 else end + 2
                blank(i, end)
                i = end
            elif c == "'":
                j = i + 1
                while j < n and text[j] not in "'\n":
                    j += 2 if text[j] == "\\" else 1
                blank(i, j + 1)
                i = j + 1
            elif c in "@$\"" and _STRING_START.match(text, i):
                i = string(i)
            elif hole and c == "{":
                depth += 1
                i += 1
            elif hole and c == "}":
                if depth == 0:
                    return i
                depth -= 1
                i += 1
            else:
                i += 1
        return n

    def string(i: int) -> int:
        prefix = _STRING_START.match(text, i).group(0)
        verbatim, interpolated = "@" in prefix, "$" in prefix
        start = j = i + len(prefix)
        while j < n:
            c = text[j]
            if c == '"':
                if verbatim and text[j + 1 : j + 2] == '"':
                    j += 2
                    continue
                break
            if not verbatim and c == "\\":
                j += 2
                continue
            if not verbatim and c == "\n":
                break  # unterminated: stop at the line's end
            if interpolated and c == "{":
                if text[j + 1 : j + 2] == "{":
                    j += 2
                    continue
                blank(start, j)
                j = code(j + 1, True)
                start = j = j + 1
                continue
            j += 1
        blank(start, j)
        return j + 1

    code(0, False)
    return "".join(out)


_DIRECTIVE = re.compile(r"^\s*#\s*(if|elif|else|endif)\b(.*)$")


def _implies(expression: str, editor: bool) -> bool:
    """Whether *expression* (a ``#if`` condition) can hold only in the editor
    (*editor*) or only outside it: every disjunct holds a conjunct that says
    so. Anything it cannot read (a negated group) implies neither."""
    if "!(" in expression.replace(" ", ""):
        return False
    want = re.compile(r"UNITY_EDITOR\w*" if editor else r"!\s*UNITY_EDITOR\w*")
    return all(
        any(want.fullmatch(term.strip(" ()\t")) for term in disjunct.split("&&"))
        for disjunct in expression.split("||")
    )


def editor_lines(code: str) -> List[bool]:
    """Per line of *code* (comments and strings already blanked), whether it
    lies in a branch that compiles only in the editor (``#if UNITY_EDITOR``,
    the ``#else`` of ``#if !UNITY_EDITOR``, any branch nested in one)."""
    stack: List[List[bool]] = []  # [this branch is editor, the #else would be]
    marks = []
    for line in code.split("\n"):  # as bypass numbers them: every '\n', nothing else
        match = _DIRECTIVE.match(line)
        if match:
            kind, expression = match.group(1), match.group(2).strip()
            if kind == "if":
                stack.append([_implies(expression, True), _implies(expression, False)])
            elif stack and kind == "elif":
                stack[-1] = [_implies(expression, True), stack[-1][1] or _implies(expression, False)]
            elif stack and kind == "else":
                stack[-1][0] = stack[-1][1]
            elif stack and kind == "endif":
                stack.pop()
            marks.append(False)
            continue
        marks.append(any(frame[0] for frame in stack))
    return marks


# ------------------------------------------------------------- the rules
_OWN = r"(?<![\w.])"
#: Each call the kernel owns: ``(pattern, editor API, the fix it names)``. An
#: editor-API call counts anywhere; a console call only in editor code.
BYPASS: Tuple[Tuple["re.Pattern[str]", bool, str], ...] = (
    (
        re.compile(_OWN + r"(?:UnityEditor\s*\.\s*)?(Undo)\s*\.\s*([A-Za-z_]\w*)"),
        True,
        "an action asks ctx.ShouldChange / ShouldCreate / ShouldDelete (each "
        "records the undo) or calls ctx.Created / Destroy / AddComponent; a menu "
        "runs it through OpContext.RunMenu (one undo group)",
    ),
    (
        re.compile(
            _OWN + r"(?:UnityEditor\s*\.\s*)?(EditorUtility)\s*\.\s*"
            r"(DisplayProgressBar|DisplayCancelableProgressBar|ClearProgressBar)\b"
        ),
        True,
        "report ctx.Progress(fraction, message); OpContext.RunMenu shows the bar "
        "and its Cancel",
    ),
    (
        re.compile(
            _OWN + r"(?:UnityEngine\s*\.\s*)?(Debug)\s*\.\s*"
            r"(Log|LogWarning|LogError|LogFormat|LogWarningFormat|LogErrorFormat|"
            r"LogException|LogAssertion|LogAssertionFormat|unityLogger)\b"
        ),
        False,
        "an action reports through ctx.Log or ctx.Issue, an importer through "
        "ImportLog.Info / Warning / Error",
    ),
)
#: Calls the rules above miss by name: the editor's progress API, and a
#: ``using static`` that turns the next call into a bare ``Log(...)``.
BYPASS += (
    (
        re.compile(_OWN + r"(?:UnityEditor\s*\.\s*)?(Progress)\s*\.\s*([A-Za-z_]\w*)"),
        True,
        "report ctx.Progress(fraction, message); OpContext.RunMenu shows the bar "
        "and its Cancel",
    ),
    (
        re.compile(
            r"(using\s+static)\s+(?:UnityEngine\s*\.\s*|UnityEditor\s*\.\s*)?"
            r"(Debug|Undo|EditorUtility|Progress)\b"
        ),
        False,
        "call the kernel's ctx / ImportLog by name; a using static hides the "
        "call from this rule",
    ),
)

# A call made only when there is a context. ``Issue`` reports a problem only to a
# context, so a script or unity.csharp.exec calling the action with none hears
# nothing; the kernel's edits and reports (OpContextEdits: Raise, Log, Created,
# Destroy, AddComponent) are extensions that work on a null context, so a null
# check skips the edit or the line then. Each is refused through ``?.``, a
# ternary (either way round) and an ``if`` guard, wrapped or not.
ISSUE_FIX = (
    "raise it with ctx.Raise(code, message, ...): an issue on the context, "
    "the Console line when there is none"
)
EXTENSION_FIX = (
    "call it as ctx.Raise / Log / Created / Destroy / AddComponent: each "
    "works with no context, and a null check skips it then"
)
_METHOD = r"(Issue|Raise|Log|Created|Destroy|AddComponent)\s*(?:<[^<>()]*>)?\s*\("
_CHAIN = r"[A-Za-z_]\w*(?:\s*\.\s*[A-Za-z_]\w*)*"
_NOT_NULL = r"\s*(?:!=\s*null|is\s+not\s+null)"
_NULL_CONDITIONAL = re.compile(r"\?\s*\.\s*" + _METHOD)
_TERNARY = re.compile(_OWN + rf"({_CHAIN}){_NOT_NULL}\s*\)?\s*\?\s*\1\s*\.\s*{_METHOD}")
_INVERTED = re.compile(
    _OWN + rf"({_CHAIN})\s*(?:==\s*null|is\s+null)\s*\?[^;?:]*:\s*\1\s*\.\s*{_METHOD}"
)
_GUARD = re.compile(rf"\bif\s*\(\s*({_CHAIN}){_NOT_NULL}\s*\)\s*")
# What makes a receiver a context. The file's own declarations type it: a field,
# parameter, local or property, an array or a collection's element, a method's
# return. Otherwise its name says it (``ctx``, ``Ctx``, ``context``, ``runCtx``):
# a lambda's parameter or another file's member has no type here. Residual: a
# receiver named like a context that is no OpContext (a ``SynchronizationContext
# context``) is refused, and an OpContext under another name that this file does
# not type (another type's ``Run``) is not.
_TYPED = (
    re.compile(r"\bOpContext\s*(?:\[\s*\]\s*)?\??\s+([A-Za-z_]\w*)"),
    re.compile(r"[<,]\s*OpContext\s*>\s*(?:\[\s*\]\s*)?([A-Za-z_]\w*)"),
    re.compile(r"\bvar\s+([A-Za-z_]\w*)\s*=\s*new\s+OpContext\b"),
)
_CONTEXT_NAME = re.compile(r"(?:ctx|context)$", re.I)


def context_names(code: str) -> set:
    """The names *code* (comments and strings blanked) declares as an
    ``OpContext``, its array or collection, or a method returning one."""
    return {match.group(1) for pattern in _TYPED for match in pattern.finditer(code)}


def _is_context(name: str, typed: set) -> bool:
    return name in typed or bool(_CONTEXT_NAME.search(name))


def _receiver(code: str, end: int) -> Optional[Tuple[str, str]]:
    """The receiver of the member access whose ``?`` sits at *end*: ``(its
    name, its key)``, an identifier's own, a call's method name (``Get()``)
    or an indexed collection's (``arr[]``); None for anything else."""
    i = end - 1
    while i >= 0 and code[i].isspace():
        i -= 1
    suffix = ""
    if i >= 0 and code[i] in ")]":
        close = code[i]
        opener = "(" if close == ")" else "["
        depth = 0
        while i >= 0:
            if code[i] == close:
                depth += 1
            elif code[i] == opener:
                depth -= 1
                if depth == 0:
                    break
            i -= 1
        if i < 0:
            return None
        suffix = opener + close
        i -= 1
        while i >= 0 and code[i].isspace():
            i -= 1
        if close == ")" and i >= 0 and code[i] == ">":  # a generic call: Get<T>()
            depth = 0
            while i >= 0:
                depth += {">": 1, "<": -1}.get(code[i], 0)
                if depth == 0:
                    break
                i -= 1
            i -= 1
            while i >= 0 and code[i].isspace():
                i -= 1
    last = i
    while i >= 0 and (code[i].isalnum() or code[i] == "_"):
        i -= 1
    name = code[i + 1 : last + 1]
    if not name or name[0].isdigit():
        return None
    return name, name + suffix


def _flat(text: str) -> str:
    return re.sub(r"\s+", "", text)


def _spaced(text: str) -> str:
    return re.sub(r"\s+", " ", text)


def _call_on(chain: str) -> "re.Pattern[str]":
    """A call of one of the guarded methods on *chain* (its spacing free)."""
    parts = [re.escape(part) for part in re.split(r"\s*\.\s*", chain.strip())]
    return re.compile(_OWN + r"\s*\.\s*".join(parts) + r"\s*\.\s*" + _METHOD)


def _block_end(code: str, start: int) -> int:
    """The offset of the brace closing the block opened at *start*."""
    depth = 0
    for k in range(start, len(code)):
        if code[k] == "{":
            depth += 1
        elif code[k] == "}":
            depth -= 1
            if depth == 0:
                return k
    return len(code)


def null_checked_calls(code: str) -> List[Tuple[int, str, str]]:
    """``[(offset, call, fix)]``: each call in *code* (comments and strings
    blanked) made only when there is a context."""
    typed = context_names(code)
    fix = lambda method: ISSUE_FIX if method == "Issue" else EXTENSION_FIX  # noqa: E731
    found = []
    for match in _NULL_CONDITIONAL.finditer(code):
        receiver = _receiver(code, match.start())
        if receiver and _is_context(receiver[0], typed):
            found.append((match.start(), f"{receiver[1]}?.{match.group(1)}", fix(match.group(1))))
    for pattern, shape in (
        (_TERNARY, "{0} != null ? {0}.{1}"),
        (_INVERTED, "{0} == null ? ... : {0}.{1}"),
    ):
        for match in pattern.finditer(code):
            chain = _flat(match.group(1))
            if _is_context(chain.split(".")[-1], typed):
                found.append((match.start(), shape.format(chain, match.group(2)), fix(match.group(2))))
    for match in _GUARD.finditer(code):
        chain = _flat(match.group(1))
        if not _is_context(chain.split(".")[-1], typed):
            continue
        call = _call_on(match.group(1))
        body = match.end()
        if code.startswith("{", body):
            calls = call.finditer(code, body, _block_end(code, body))
        else:
            calls = filter(None, [call.match(code, body)])
        for hit in calls:
            found.append((match.start(), f"if ({chain} != null) {chain}.{hit.group(1)}", fix(hit.group(1))))
    return found


#: What a test assembly needs besides UNITY_INCLUDE_TESTS: a define only the
#: Test Framework's presence sets, so a project without it (an embedded
#: deploy) never compiles the tests.
TEST_FRAMEWORK = "com.unity.test-framework"
TEST_FRAMEWORK_FIX = (
    "add a versionDefines row on com.unity.test-framework and its define to "
    "defineConstraints (the scaffold writes both)"
)
PRIOR_ART_FIX = (
    "write what the part weighed, and why it was or was not adopted, under "
    "'Prior art:' in its main type's <remarks>"
)


def _sources(layout: "cl.CSharpLayout") -> Iterable[Tuple[Path, Optional["cl.Asmdef"]]]:
    """Each ``.cs`` file under the root and the asmdef it compiles into."""
    for path in cl.unity_walk(layout.root, ".cs"):
        yield path, layout.assembly_of(path)


def _exempt(layout: "cl.CSharpLayout", path: Path, asmdef) -> bool:
    if path.name.endswith(".g.cs") or asmdef is None:
        return True  # generated, or in no assembly of the package
    return asmdef.is_test or layout.at_or_below_kernel(asmdef)


def bypass(layout: "cl.CSharpLayout") -> Dict[str, str]:
    """``{key: where and the fix}`` for each call rule 1 forbids. The whole
    file is read at once, so a call wrapped over lines counts, placed at its
    first line."""
    found: Dict[str, str] = {}
    counts: Dict[str, int] = {}
    for path, asmdef in _sources(layout):
        if _exempt(layout, path, asmdef):
            continue
        code = code_only(path.read_text(encoding="utf-8-sig", errors="replace"))
        editor = editor_lines(code)
        starts = [0] + [k + 1 for k, c in enumerate(code) if c == "\n"]
        hits = [
            (match.start(), editor_api, f"{_spaced(match.group(1))}.{match.group(2)}", fix)
            for pattern, editor_api, fix in BYPASS
            for match in pattern.finditer(code)
        ]
        hits += [(offset, True, call, fix) for offset, call, fix in null_checked_calls(code)]
        for offset, editor_api, call, fix in sorted(hits, key=lambda hit: hit[0]):
            number = bisect.bisect_right(starts, offset)
            if not (editor_api or asmdef.editor_only or editor[number - 1]):
                continue
            call = f"{path.name}: {call}"
            counts[call] = counts.get(call, 0) + 1
            nth = counts[call]
            key = f"bypass: {call}" + (f" ({nth})" if nth > 1 else "")
            found[key] = f"at {layout.rel(path)}:{number}: {fix}"
    return found


_DOC = re.compile(r"^\s*///(.*)$")
_TYPE = re.compile(
    r"^\s*(?:\[.*\]\s*)*(?:(?:public|internal|private|protected|static|sealed|"
    r"abstract|partial|readonly|unsafe|new|ref)\s+)*"
    r"(?:class|struct|interface|enum|record|delegate)\b"
)
# A record, not the scaffold's placeholder: "Prior art: TODO" says nothing yet.
_PRIOR_ART = re.compile(r"<remarks>(?:(?!</remarks>).)*Prior\s+art:(?!\s*TODO)", re.S)


def declares_prior_art(text: str) -> bool:
    """Whether *text* declares a type whose ``///`` doc has ``Prior art:`` in
    its ``<remarks>`` (attribute lines may sit between the doc and the type)."""
    lines = text.splitlines()
    index = 0
    while index < len(lines):
        if not _DOC.match(lines[index]):
            index += 1
            continue
        doc = []
        while index < len(lines) and _DOC.match(lines[index]):
            doc.append(_DOC.match(lines[index]).group(1))
            index += 1
        after = index
        while after < len(lines) and (
            not lines[after].strip() or lines[after].strip().startswith("[")
        ) and not _TYPE.match(lines[after]):
            after += 1
        if (
            after < len(lines)
            and _TYPE.match(lines[after])
            and _PRIOR_ART.search(" ".join(doc))
        ):
            return True
    return False


def prior_art(layout: "cl.CSharpLayout") -> Dict[str, str]:
    """``{key: the fix}`` for each part assembly rule 2 finds without one."""
    weighed = set()
    for path, asmdef in _sources(layout):
        if asmdef is not None and asmdef.name not in weighed:
            if declares_prior_art(path.read_text(encoding="utf-8-sig", errors="replace")):
                weighed.add(asmdef.name)
    return {
        f"prior-art: {a.name}.asmdef": (
            f"no type in {layout.rel(a.path)}'s assembly says it: {PRIOR_ART_FIX}"
        )
        for a in layout.asmdefs
        if not a.is_test and a.name not in weighed
    }


def test_framework(layout: "cl.CSharpLayout") -> List[str]:
    """What rule 4 finds: each test assembly that would compile without the
    Test Framework: its ``defineConstraints`` lacks a define only a
    ``versionDefines`` row on ``com.unity.test-framework`` sets. Never frozen."""
    found = []
    for asmdef in layout.asmdefs:
        if not asmdef.is_test:
            continue
        rows = asmdef.data.get("versionDefines") or []
        defines = {r.get("define") for r in rows if isinstance(r, dict) and r.get("name") == TEST_FRAMEWORK}
        if not defines & set(asmdef._list("defineConstraints")):
            found.append(f"test-framework: {layout.rel(asmdef.path)} compiles without the Test Framework: {TEST_FRAMEWORK_FIX}")
    return found


_GENERATOR = re.compile(r"m3trik/scripts/\w+\.py")


def generator_of(path: Path) -> Optional[str]:
    """The generator a ``*.g.cs``'s ``// <auto-generated>`` header names, or None."""
    lines = path.read_text(encoding="utf-8-sig", errors="replace").splitlines()[:12]
    if not lines or lines[0].strip() != "// <auto-generated>":
        return None
    for line in lines[1:]:
        if line.strip() == "// </auto-generated>":
            break
        match = _GENERATOR.search(line)
        if match:
            return match.group(0)
    return None


def _within(path: Path, folder: Path) -> bool:
    try:
        path.relative_to(folder)
        return True
    except ValueError:
        return False


def generated(
    layout: "cl.CSharpLayout",
    generators: Optional[Dict[str, Callable[[], List[Tuple[Path, str]]]]] = None,
) -> List[str]:
    """What rule 3 finds wrong with the package's generated files."""
    generators = GENERATORS if generators is None else generators
    problems: List[str] = []
    written: Dict[str, Optional[Dict[Path, str]]] = {}
    repo = layout.repo.resolve()

    def output(script: str) -> Optional[Dict[Path, str]]:
        if script not in written:
            try:
                written[script] = {
                    Path(p).resolve(): text for p, text in generators[script]()
                }
            except Exception as error:  # an absent pythontk, a broken declaration
                written[script] = None
                problems.append(
                    f"{script} could not run ({type(error).__name__}: {error}): "
                    "check out pythontk beside m3trik, then run it"
                )
        return written[script]

    def drifted(path: Path, want: str) -> bool:
        have = path.read_bytes().decode("utf-8", "replace") if path.is_file() else None
        return have is None or have.replace("\r\n", "\n") != want

    known = " or ".join(generators)
    for path in cl.unity_walk(layout.root, ".g.cs"):
        rel = layout.rel(path)
        script = generator_of(path)
        if script is None:
            problems.append(
                f"{rel}: no '// <auto-generated>' header naming its generator: a "
                f"*.g.cs is written by {known}, never by hand"
            )
            continue
        if script not in generators:
            problems.append(
                f"{rel}: its header names {script}, which writes no C# this check "
                "knows: add it to check_csharp.GENERATORS"
            )
            continue
        out = output(script)
        if out is None:
            continue
        resolved = path.resolve()
        if resolved not in out:
            problems.append(
                f"{rel}: {script} does not write it: delete it, or declare it in "
                f"Python and run python {script}"
            )
            continue
        meta = resolved.with_name(resolved.name + ".meta")
        for file in (resolved, meta):
            if file in out and file.is_file() and drifted(file, out[file]):
                problems.append(
                    f"{layout.rel(file)}: differs from what {script} writes (a hand "
                    f"edit, or a stale file): change its declaration in Python, then "
                    f"run python {script}"
                )
    for script in generators:
        out = output(script) or {}
        for target in sorted(out):
            if not _within(target, repo):
                continue  # another repo's file
            if not _within(target, layout.root):
                problems.append(
                    f"{script} writes {target.relative_to(repo).as_posix()}, outside "
                    f"the declared C# root {layout.rel(layout.root) or '.'}: point "
                    "it at the package"
                )
            elif not target.is_file():
                problems.append(
                    f"{layout.rel(target)} is missing: run python {script}"
                )
    return problems


# --------------------------------------------------------------- scanning
def scan(
    workspace: Path = WORKSPACE,
    packages: Optional[Sequence[str]] = None,
    generators: Optional[Dict[str, Callable[[], List[Tuple[Path, str]]]]] = None,
) -> Tuple[Dict[str, Dict[str, str]], List[str], Dict[str, List[str]]]:
    """``({package: {violation: where and the fix}}, [declaration problems],
    {package: [strict failures]})`` over each ecosystem package that declares
    its C# parts, or the *packages* named from them."""
    violations: Dict[str, Dict[str, str]] = {}
    strict: Dict[str, List[str]] = {}
    problems: List[str] = []
    for package in cl._sync_workspace().ecosystem_packages():
        if packages and package not in packages:
            continue
        repo = workspace / package
        if not (repo / "pyproject.toml").is_file():
            continue  # partial checkout
        try:
            declared = cl.csharp(cl.pyproject(repo))
        except cl.tomllib.TOMLDecodeError as error:
            problems.append(f"{package}: pyproject.toml does not parse ({error})")
            continue
        if declared is None:
            undeclared = cl.undeclared_csharp(repo, package)
            if undeclared:
                problems.append(f"{package}: {undeclared}")
            elif packages:
                problems.append(
                    f"{package}: declares no [tool.m3trik.layers.csharp]: declare its "
                    "C# parts (check_layers.py, rule 5) or name another package"
                )
            continue
        layout = cl.CSharpLayout(repo, declared)
        problems += [f"{package}: {p}" for p in layout.problems]
        found = bypass(layout)
        found.update(prior_art(layout))
        violations[package] = found
        strict[package] = generated(layout, generators)
        strict[package] += test_framework(layout)
    return violations, problems, strict


def baseline_file(workspace: Path = WORKSPACE) -> Path:
    """The baseline frozen from *workspace* (its own copy of this one)."""
    return workspace / BASELINE.relative_to(WORKSPACE)


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    mode = parser.add_mutually_exclusive_group()
    mode.add_argument("--check", action="store_true", help="the default")
    mode.add_argument(
        "--update", action="store_true", help="freeze the current violations"
    )
    parser.add_argument(
        "--workspace", type=Path, default=WORKSPACE, help="the monorepo root"
    )
    parser.add_argument(
        "packages", nargs="*", help="check only these (default: every C# package)"
    )
    args = parser.parse_args(argv)
    if args.update and args.packages:
        parser.error("--update rewrites the whole baseline: name no packages")

    violations, problems, strict = scan(args.workspace, args.packages)
    for problem in problems:
        print(f"[FAIL] declaration: {problem}")
    for package, found in strict.items():
        for failure in found:
            print(f"[FAIL] {package}: generated: {failure} (strict: never frozen)")
    strict_total = sum(len(v) for v in strict.values())
    frozen_file = baseline_file(args.workspace)
    keys = {package: sorted(found) for package, found in violations.items()}
    if args.update:
        # A package the scan could not read keeps its frozen entries.
        merged = {**cl.load_baseline(frozen_file), **keys}
        frozen_file.parent.mkdir(parents=True, exist_ok=True)
        cl.write_baseline(merged, frozen_file, BASELINE_DOC)
        total = sum(len(v) for v in merged.values())
        print(f"[WROTE] {frozen_file}: {total} frozen violation(s)")
        return 1 if problems or strict_total else 0
    if not violations and not problems:
        print("[SKIP] no package declares [tool.m3trik.layers.csharp]")
    new_total = cl.compare(
        keys,
        cl.load_baseline(frozen_file),
        lambda package, key: violations[package].get(key, ""),
    )
    return 1 if new_total or problems or strict_total else 0


if __name__ == "__main__":
    sys.exit(main())
